*{
    line-height: 2;
    margin: 0;
    padding: 0;
    font-family: 'Trebuchet MS', 'Lucida Sans Unicode', 'Lucida Grande', 'Lucida Sans', Arial, sans-serif;
}
header{
    background-image: url(filesProjet4/fond.png);
    background-repeat: no-repeat;
    background-size: cover;
    height: 80px;

}
h1{
    color: #FDF0D1;
    text-align: center;
}
#date{
    text-align: right;
    color: #FDF0D1;
    font-weight: bold;

}
ul{
    list-style: none;
    padding-top:  1.5%;
}
nav{
    text-align: center;
}
li{
    display: inline-block;
    background-color: #616d82;
    border: 1px solid #fdf0d1;
    width: 180px;
    text-align: center;
    border-radius: 10px;
    padding: 2px;
}
a{
    text-decoration: none;
    color: #fdf0d1;
    font-weight: bold;
}
main{
    height: 590px;
    background-color:#FDF0D1 ;
    margin: auto;

}
section{
    width: 60%;
    height: 430px;
    margin: auto;
    margin-top: 2.8%;
    box-shadow: 1px 2px 3px 8px rgba(49,12,40,0.5);
}
iframe{
    width: 100%;
    height: 100%;
}
footer{
    background-color: #616d81;
    height: 60px;
}
p{
    color: #FDF0D1;
    text-align: right;
}
input[type="text"],input[type="number"]{
    border: 1px solid black;
    border-radius: 10px;
    width: 300px;
    height: 40px;
    margin: 2%;
    text-align: center;
}
input[type="reset"],input[type="submit"]{
    border: 1px solid;
    width: 90px;
}
form{
    text-align: center;
    width: 100%;
    height: 100%;
    margin: auto;
}
fieldset{
    height: 70%;
    width: 70%;
    margin: auto;
}
legend{
    text-decoration: underline;
    font-weight: bold;
}
table tr td{
    border: 3px black solid;
    table-layout: fixed;
}
select{
    width: 250px;
    height: 20px;
}

